-- db/seed/pitch/09-weekly-year.sql
-- GENERATED by db/seed/pitch/build_weekly_year.py — edit the generator.
--
-- The Free Weekly NCLEX Q&A becomes a full year: 52 weeks, each with a
-- taught NCLEX topic (~25 min) followed by the open floor (~30 min).
--
-- Weeks 1-51 carry one Client Needs subcategory each; week 52 is the
-- finale. Across the 51 teaching weeks every subcategory lands inside
-- its published NCSBN range:
--
--   Management of Care                          8 weeks  15.7%  (15-21%)
--   Safety and Infection Control                7 weeks  13.7%  (10-16%)
--   Health Promotion and Maintenance            5 weeks   9.8%  (6-12%)
--   Psychosocial Integrity                      5 weeks   9.8%  (6-12%)
--   Basic Care and Comfort                      5 weeks   9.8%  (6-12%)
--   Pharmacological and Parenteral Therapies    8 weeks  15.7%  (13-19%)
--   Reduction of Risk Potential                 6 weeks  11.8%  (9-15%)
--   Physiological Adaptation                    7 weeks  13.7%  (11-17%)
--
-- Four terms of 13, each touching all eight areas in proportion, so
-- joining cold in any term still gives representative coverage.
--
-- Weeks 6, 17, 22, 29, 34, 40 point at the paid maternity
-- programmes from 08-maternity.sql (the activity `note` field).
--
-- Live sessions are dated for TERM 1 ONLY (weeks 1-13).
-- Terms 2-4 are published with their topic and no date, because 52
-- dated sessions is a year-long promise a tutor should make a term at
-- a time.
--
-- Requires 08-maternity.sql (the programme row and the six notes it
-- cross-sells). Idempotent throughout.

BEGIN;

-- ====================================================================
-- 1. The programme — 4 weeks becomes 52
-- ====================================================================
-- Upsert rather than UPDATE so the file stands alone if the programme
-- was never seeded. Either path fires a unit trigger (seed_units on
-- INSERT, reconcile_units on the length_units change), both of which
-- create blank units with random ids — section 2 clears them.

INSERT INTO nclex_programmes (
  programme_id, tutor_id, title, tagline, description,
  delivery_mode, unit_label, length_units,
  price_currency, show_price_publicly, payment_collection_mode,
  access_window_days, payment_gates_access, status, published_at
) VALUES (
  '80000000-0000-4000-8000-000000000004', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
  'Free Weekly NCLEX Q&A',
  'A free taught session every Tuesday, all year — weighted to the real test plan. Recordings the same evening.',
  'Every Tuesday evening I teach one NCLEX topic for about twenty-five minutes, and then the floor is open for as long as you have questions. It is free, and it always will be.

The year is not a random list of topics. All eight NCLEX Client Needs areas appear across the 52 weeks in the same proportions the real exam uses, so a candidate who attends for a year has been taught the test plan — not somebody''s favourite subjects. The year runs in four terms of thirteen weeks, and every term touches all eight areas, so it does not matter which week you start.

Sessions are recorded and posted here the same evening, so a shift does not cost you the week. Join the cohort and you get the joining link, the full 52-week plan and every recording so far.

Who comes: candidates at every stage, including people who have not decided whether they want a paid programme at all. That is fine. Come and see how I teach before you spend anything.',
  'TUTOR_LED', 'WEEK', 52,
  'GHS', TRUE, 'ON_PLATFORM',
  NULL, FALSE, 'PUBLISHED', NOW()
)
ON CONFLICT (programme_id) DO UPDATE SET
  title = EXCLUDED.title, tagline = EXCLUDED.tagline,
  description = EXCLUDED.description, delivery_mode = EXCLUDED.delivery_mode,
  unit_label = EXCLUDED.unit_label, length_units = EXCLUDED.length_units,
  access_window_days = EXCLUDED.access_window_days,
  show_price_publicly = EXCLUDED.show_price_publicly,
  payment_gates_access = EXCLUDED.payment_gates_access,
  status = 'PUBLISHED', updated_at = NOW();

-- ====================================================================
-- 2. Clear the trigger's blank units
-- ====================================================================
-- Must run AFTER section 1 and BEFORE section 3: the trigger's rows
-- carry random ids and collide with ours on (programme_id, unit_index).

DELETE FROM nclex_programme_units
WHERE  programme_id = '80000000-0000-4000-8000-000000000004'
  AND  unit_id::text NOT LIKE '81000000-0000-4000-8000-004%';

-- ====================================================================
-- 3. Fifty-two weeks
-- ====================================================================
