-- ====================================================================
-- 6. The cohort — one cycle, running now
-- ====================================================================
-- The programme's own description promises a cohort ('join the cohort
-- and you get the joining link'), and until now there was not one.
--
-- start_date is the Tuesday on or before CURRENT_DATE - 56, so eight
-- weeks have already aired and carry recordings. That is deliberate:
-- the back catalogue is the reason joining late is attractive rather
-- than a problem. Anchored to the weekday rather than a raw offset,
-- because the cohort is named 'Tuesdays' and the first thing anyone
-- reads is the date beside that name.
--
-- allow_late_join is TRUE — a rolling free year that you could not
-- join in week 30 would be a strange thing to publish. No size cap.

INSERT INTO nclex_cohorts (
  cohort_id, programme_id, name, start_date, end_date,
  cohort_size, allow_late_join
)
SELECT
  '86000000-0000-4000-8000-000000000004'::uuid, '80000000-0000-4000-8000-000000000004',
  'Tuesdays 19:00 GMT — the 2026 cycle',
  v.start_date, v.start_date + 363, NULL, TRUE
FROM (
  SELECT (CURRENT_DATE - 56)
    - ((EXTRACT(DOW FROM CURRENT_DATE - 56)::int - 2 + 7) % 7) AS start_date
) AS v
ON CONFLICT (cohort_id) DO UPDATE SET
  name = EXCLUDED.name,
  start_date = EXCLUDED.start_date, end_date = EXCLUDED.end_date,
  cohort_size = EXCLUDED.cohort_size,
  allow_late_join = EXCLUDED.allow_late_join,
  cancelled_at = NULL, updated_at = NOW();

-- ====================================================================
-- 7. Cohort checklist — all 52 weeks
-- ====================================================================
-- For a TUTOR_LED programme the student sees the curriculum THROUGH
-- these rows: no checklist row, no activity. All 52 are written, not
-- just the scheduled term — the complete year is the thing worth
-- joining for, and an undated week still shows its topic.
--
-- release_date follows the app's own week pacing
-- (lib/curriculum/cohort-attach.ts): start_date + (unit_index - 1) x 7.

INSERT INTO nclex_cohort_checklist_items (
  cohort_id, template_activity_id, is_included,
  release_date, due_date, close_date, source
)
SELECT
  c.cohort_id, a.activity_id, TRUE,
  c.start_date + ((u.unit_index - 1) * 7),
  NULL, NULL, 'TEMPLATE'
FROM   nclex_cohorts c
JOIN   nclex_programme_units u      ON u.programme_id = c.programme_id
JOIN   nclex_programme_activities a ON a.unit_id = u.unit_id
WHERE  c.cohort_id = '86000000-0000-4000-8000-000000000004'
  AND  a.cohort_id IS NULL
ON CONFLICT (cohort_id, template_activity_id) DO UPDATE SET
  is_included = TRUE,
  release_date = EXCLUDED.release_date,
  updated_at = NOW();

-- ====================================================================
-- 8. Live-session planner — TERM 1 ONLY (weeks 1-13)
-- ====================================================================
-- Terms 2-4 deliberately have no rows: published topic, no date. The
-- tutor schedules the next term when they are ready to commit to it.
--
-- The date is derived from the cohort row rather than recomputing the
-- CURRENT_DATE arithmetic of section 6 — two copies of that sum would
-- eventually disagree, and this is what students turn up on.
--
-- Anything already past carries a recording, which is what makes the
-- back catalogue visible in the pitch.

INSERT INTO nclex_cohort_live_sessions (
  session_id, cohort_id, marker_activity_id,
  scheduled_at, duration_minutes, platform,
  join_url, meeting_id, passcode, joining_instructions, recording_url
)
SELECT
  ('87000000-0000-4000-8000-004' || lpad(w::text,3,'0') || '000000')::uuid,
  c.cohort_id,
  ('83000000-0000-4000-8000-004' || lpad(w::text,3,'0') || '001001')::uuid,
  c.start_date::timestamptz + INTERVAL '19 hours'
    + ((w - 1) * INTERVAL '7 days'),
  60, 'ZOOM',
  'https://us06web.zoom.us/j/97700112233', '977 0011 2233', 'NCLEX',
  'Free and open — no registration beyond joining the cohort. Come for the taught part, stay for the questions, or just lurk. Recording goes up the same evening.',
  CASE WHEN c.start_date::timestamptz + INTERVAL '19 hours'
            + ((w - 1) * INTERVAL '7 days') < NOW()
       THEN 'https://example.com/mynclex/recordings/weekly/week-' || w
       ELSE NULL END
FROM generate_series(1,13) w
CROSS JOIN nclex_cohorts c
WHERE c.cohort_id = '86000000-0000-4000-8000-000000000004'
ON CONFLICT (cohort_id, marker_activity_id) DO UPDATE SET
  scheduled_at = EXCLUDED.scheduled_at,
  duration_minutes = EXCLUDED.duration_minutes,
  platform = EXCLUDED.platform,
  join_url = EXCLUDED.join_url,
  meeting_id = EXCLUDED.meeting_id,
  passcode = EXCLUDED.passcode,
  joining_instructions = EXCLUDED.joining_instructions,
  recording_url = EXCLUDED.recording_url,
  updated_at = NOW();

COMMIT;
